// dart format width=80
// ignore_for_file: unused_local_variable, unused_import
// Generated by `drift_dev make-migrations` (Phase 3); the data tests below
// replace its template.
import 'package:connect_hub_riverpod/core/database/app_database.dart';
import 'package:drift/drift.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flutter_test/flutter_test.dart';

import 'generated/schema.dart';

import 'generated/schema_v1.dart' as v1;
import 'generated/schema_v2.dart' as v2;

void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() {
    verifier = SchemaVerifier(GeneratedHelper());
  });

  group('simple database migrations', () {
    // These simple tests verify all possible schema updates with a simple (no
    // data) migration. This is a quick way to ensure that written database
    // migrations properly alter the schema.
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      group('from $fromVersion', () {
        for (final toVersion in versions.skip(i + 1)) {
          test('to $toVersion', () async {
            final schema = await verifier.schemaAt(fromVersion);
            final db = AppDatabase(schema.newConnection());
            await verifier.migrateAndValidate(db, toVersion);
            await db.close();
          });
        }
      });
    }
  });

  // A cache with data in it survives the upgrade unchanged, and the new
  // comments table works with it (its foreign key and cascade included).
  test('v1 → v2 keeps the cached feed and saves, and adds comments', () async {
    // The schema snapshots hold raw SQL values: dates as ISO-8601 text
    // (see build.yaml), booleans as 0 / 1.
    final createdAt = DateTime.utc(2026, 10, 11, 11).toIso8601String();
    final savedAt = DateTime.utc(2026, 10, 11, 12).toIso8601String();
    const ada = v1.UsersData(
      id: 'u_ada',
      name: 'Ada Lovelace',
      bio: 'Engines',
      followersCount: 10,
      followingCount: 2,
    );
    final p1 = v1.PostsData(
      id: 'p1',
      authorId: 'u_ada',
      content: 'Hello',
      createdAt: createdAt,
      likeCount: 142,
      commentCount: 3,
      isLiked: 1,
    );

    await verifier.testWithDataIntegrity(
      oldVersion: 1,
      newVersion: 2,
      createOld: v1.DatabaseAtV1.new,
      createNew: v2.DatabaseAtV2.new,
      openTestedDatabase: AppDatabase.new,
      createItems: (batch, oldDb) {
        batch
          ..insertAll(oldDb.users, [ada])
          ..insertAll(oldDb.posts, [p1])
          ..insertAll(oldDb.feedItems, [const v1.FeedItemsData(postId: 'p1')])
          ..insertAll(oldDb.bookmarks, [
            v1.BookmarksData(postId: 'p1', bookmarkedAt: savedAt),
          ]);
      },
      validateItems: (newDb) async {
        expect(await newDb.select(newDb.users).get(), [
          const v2.UsersData(
            id: 'u_ada',
            name: 'Ada Lovelace',
            bio: 'Engines',
            followersCount: 10,
            followingCount: 2,
          ),
        ]);
        expect(await newDb.select(newDb.posts).get(), [
          v2.PostsData(
            id: 'p1',
            authorId: 'u_ada',
            content: 'Hello',
            createdAt: createdAt,
            likeCount: 142,
            commentCount: 3,
            isLiked: 1,
          ),
        ]);
        expect(await newDb.select(newDb.feedItems).get(), [
          const v2.FeedItemsData(postId: 'p1'),
        ]);
        expect(await newDb.select(newDb.bookmarks).get(), [
          v2.BookmarksData(postId: 'p1', bookmarkedAt: savedAt),
        ]);
        expect(await newDb.select(newDb.comments).get(), isEmpty);
      },
    );
  });

  test(
    'after v1 → v2, a comment can be cached and goes with its post',
    () async {
      final schema = await verifier.schemaAt(1);
      final oldDb = v1.DatabaseAtV1(schema.newConnection());
      await oldDb
          .into(oldDb.users)
          .insert(
            const v1.UsersData(
              id: 'u_ada',
              name: 'Ada',
              bio: '',
              followersCount: 0,
              followingCount: 0,
            ),
          );
      await oldDb
          .into(oldDb.posts)
          .insert(
            v1.PostsData(
              id: 'p1',
              authorId: 'u_ada',
              content: 'Hello',
              createdAt: DateTime.utc(2026, 10, 11).toIso8601String(),
              likeCount: 0,
              commentCount: 0,
              isLiked: 0,
            ),
          );
      await oldDb.close();

      final db = AppDatabase(schema.newConnection());
      addTearDown(db.close);
      await verifier.migrateAndValidate(db, 2);
      await db
          .into(db.comments)
          .insert(
            CommentRow(
              id: 'c1',
              postId: 'p1',
              authorId: 'u_ada',
              content: 'First!',
              createdAt: DateTime.utc(2026, 10, 11, 1),
              likeCount: 0,
              isLiked: false,
            ),
          );
      expect(await db.select(db.comments).get(), hasLength(1));

      await db.postsDao.deletePost('p1');
      expect(await db.select(db.comments).get(), isEmpty);
    },
  );
}
